<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { detalleCliente, listarClientes, registrarCliente } from '../services/clientes'
import type { Cliente } from '../interfaces/clientes.interface'
const rows=ref<Cliente[]>([]),total=ref(0),page=ref(1),lastPage=ref(1),criterion=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Cliente|null>(null)
const form=reactive({tipo:1 as 1|2,nombre:'',apellido_paterno:'',apellido_materno:'',dni:'',razon_social:'',ruc:'',celular:'',telefono_fijo:'',email:''})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarClientes(criterion.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(){Object.assign(form,{tipo:1,nombre:'',apellido_paterno:'',apellido_materno:'',dni:'',razon_social:'',ruc:'',celular:'',telefono_fijo:'',email:''});modal.value=true}
async function save(){if(!/^\d{9}$/.test(form.celular)||!/^\S+@\S+\.\S+$/.test(form.email)){error.value='Ingrese un celular de 9 dígitos y un correo válido.';return}if(form.tipo===1&&(!form.nombre||!form.apellido_paterno||!form.apellido_materno||!/^\d{8}$/.test(form.dni))){error.value='Complete los nombres y un DNI válido de 8 dígitos.';return}if(form.tipo===2&&(!form.razon_social||!/^\d{11}$/.test(form.ruc))){error.value='Ingrese la razón social y un RUC válido de 11 dígitos.';return}saving.value=true;error.value='';try{const r=await registrarCliente(form);modal.value=false;success.value='Cliente registrado correctamente.';detail.value=await detalleCliente(r.id);await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Cliente){try{detail.value=await detalleCliente(item.id)}catch(e){error.value=message(e)}}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Comercialización / Clientes</nav><header class="hero"><div class="mark">CL</div><div><small>EVAN · COMERCIALIZACIÓN</small><h1>Clientes comerciales</h1><p>Consulta integral de personas, predios, conexiones y trámites.</p></div><strong>{{total}} resultados</strong><button @click="open">+ Registrar cliente</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="search"><label>Buscar persona<input v-model.trim="criterion" placeholder="Nombre, apellidos, DNI o RUC" @keyup.enter="load(1)"></label><button @click="load(1)">Buscar</button></section><div v-if="loading" class="empty">Buscando clientes…</div><div v-else-if="!rows.length" class="empty">No se encontraron registros. Ingrese un nombre o documento para buscar.</div><section v-else class="cards"><article v-for="item in rows" :key="item.id"><div class="avatar">{{item.tipo===2?'PJ':'PN'}}</div><h2>{{item.nombre_completo}}</h2><strong>{{item.dni||item.ruc||'Sin documento'}}</strong><p>{{item.celular||'Sin celular'}} · {{item.correo||'Sin correo'}}</p><div class="counts"><span><b>{{item.predios_count||0}}</b>Predios</span><span><b>{{item.conexiones_count||0}}</b>Conexiones</span><span><b>{{item.tramites_count||0}}</b>Trámites</span></div><button @click="show(item)">Ver información</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO REGISTRO</small><h2>Registrar cliente</h2></div><button type="button" @click="modal=false">×</button></header><div class="type"><button type="button" :class="{active:form.tipo===1}" @click="form.tipo=1">Persona natural</button><button type="button" :class="{active:form.tipo===2}" @click="form.tipo=2">Persona jurídica</button></div><div v-if="form.tipo===1" class="grid"><label>Nombres *<input v-model.trim="form.nombre" minlength="2"></label><label>Apellido paterno *<input v-model.trim="form.apellido_paterno" minlength="2"></label><label>Apellido materno *<input v-model.trim="form.apellido_materno" minlength="2"></label><label>DNI *<input v-model.trim="form.dni" maxlength="8" inputmode="numeric"></label></div><div v-else class="grid"><label>Razón social *<input v-model.trim="form.razon_social" minlength="2"></label><label>RUC *<input v-model.trim="form.ruc" maxlength="11" inputmode="numeric"></label></div><h3>Datos de contacto</h3><div class="grid"><label>Celular *<input v-model.trim="form.celular" maxlength="9" inputmode="numeric"></label><label>Teléfono fijo<input v-model.trim="form.telefono_fijo" inputmode="numeric"></label><label>Correo electrónico *<input v-model.trim="form.email" type="email"></label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar cliente'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>FICHA COMERCIAL</small><h2>{{detail.nombre_completo}}</h2><p>{{detail.dni||detail.ruc}} · {{detail.celular}} · {{detail.correo}}</p></div><button @click="detail=null">×</button></header><h3>Predios y conexiones</h3><div class="properties"><p v-if="!detail.predios?.length">Esta persona no cuenta con predios registrados.</p><article v-for="predio in detail.predios" :key="predio.id"><header><div><b>{{predio.direccion_completa}}</b><small>{{predio.distrito}} · Sector {{predio.sector}} · Mz. {{predio.manzana}} · Lote {{predio.lote}}</small></div><span>{{predio.fotografias_count||0}} fotos</span></header><div v-for="connection in predio.conexiones" :key="connection.id" class="connection"><b>{{connection.codigo}}</b><span>{{connection.situacion}}</span><span>{{connection.categoria||'Sin categoría'}}</span><em v-for="service in connection.servicios" :key="service.id">{{service.nombre}}</em></div></article></div><h3>Últimos trámites</h3><div class="procedures"><p v-if="!detail.tramites?.length">Sin trámites registrados.</p><div v-for="x in detail.tramites" :key="x.id"><b>{{x.numero||'#'+x.id}} · {{x.tipo}}</b><span>{{x.asunto}}</span><em>{{x.estado}} · {{x.fecha}}</em></div></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#21a06b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.6rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p,.modal header p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.search button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.search{margin-top:13px;padding:12px;display:flex;align-items:end;gap:8px;border-radius:9px;background:#fff}.search label{flex:1;font-size:.53rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.cards article{padding:15px;text-align:center;border-top:3px solid var(--accent);border-radius:9px;background:#fff}.avatar{width:55px;height:55px;margin:auto;display:grid;place-items:center;border-radius:50%;color:#fff;background:#6b7c84;font-size:.55rem;font-weight:700}.cards h2{min-height:35px;font-size:.65rem}.cards article>strong,.cards article>p{display:block;color:#728087;font-size:.52rem}.counts{margin:12px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.counts span{font-size:.47rem}.counts b{display:block;color:var(--accent);font-size:.65rem}.cards article>button{border:0;color:var(--accent);background:none;font-size:.52rem;font-weight:700}.empty{margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,760px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.type{margin:12px 0;display:flex}.type button{flex:1;padding:9px;border:1px solid #dbe2e5;background:#fff;font-size:.56rem}.type button.active{color:#fff;background:var(--accent)}.modal h3{font-size:.65rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.detail{width:min(100%,950px)}.properties>article{margin-bottom:8px;border:1px solid #e2e8ea;border-radius:7px}.properties article>header{padding:9px;display:flex;justify-content:space-between;background:#f3f6f7;font-size:.55rem}.properties header b,.properties header small{display:block}.connection{padding:8px;display:grid;grid-template-columns:90px 90px 1fr auto;gap:6px;border-top:1px solid #edf0f2;font-size:.53rem}.connection em{padding:3px 6px;border-radius:8px;color:#287153;background:#eff9f4;font-style:normal}.procedures div{padding:8px;display:grid;grid-template-columns:150px 1fr auto;gap:7px;border-bottom:1px solid #edf0f2;font-size:.53rem}.procedures em{font-style:normal;color:#718087}@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}.hero{flex-wrap:wrap}.hero strong{margin-left:0}.connection,.procedures div{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cards,.grid{grid-template-columns:1fr}.search{align-items:stretch;flex-direction:column}}
</style>
